// Общий помощник API-тестов: запрос к Supabase REST/RPC из страницы с токеном и apikey сохранённой сессии (без паролей).
import type { Page } from '@playwright/test';
import { expect } from '@playwright/test';

export type ApiRes = { status: number; body: any; contentRange: string | null };

/** Открывает сайт под сессией страницы и ждёт, пока в localStorage появится токен. */
export async function openApp(page: Page) {
  await page.goto('/');
  await expect.poll(() => page.evaluate(() => Object.keys(localStorage).some((k) => k.includes('auth-token'))), { timeout: 30_000 }).toBe(true);
}

/** REST/RPC-запрос от имени пользователя страницы. path — после /rest/v1/ (например 'orders?select=id' или 'rpc/approve_order'). */
export async function sb(page: Page, method: string, path: string, body?: unknown, prefer?: string): Promise<ApiRes> {
  return page.evaluate(
    async ({ method, path, body, prefer }) => {
      const w = window as any;
      if (!w.__qaKey) {
        for (const src of [...document.scripts].map((s) => s.src).filter(Boolean)) {
          const t = await (await fetch(src)).text();
          const m = t.match(/eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/);
          if (m) { w.__qaKey = m[0]; break; }
        }
      }
      const key: string = w.__qaKey;
      const tokenKey = Object.keys(localStorage).find((k) => k.includes('auth-token'))!;
      const token = JSON.parse(localStorage.getItem(tokenKey)!).access_token;
      const ref = JSON.parse(atob(key.split('.')[1])).ref as string;
      const headers: Record<string, string> = { apikey: key, Authorization: `Bearer ${token}` };
      if (body !== undefined) headers['Content-Type'] = 'application/json';
      if (prefer) headers['Prefer'] = prefer;
      const r = await fetch(`https://${ref}.supabase.co/rest/v1/${path}`, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
      const text = await r.text();
      let parsed: any = null;
      try { parsed = text ? JSON.parse(text) : null; } catch { parsed = text; }
      return { status: r.status, body: parsed, contentRange: r.headers.get('content-range') };
    },
    { method, path, body, prefer },
  );
}

/** Точное число строк запроса (Prefer: count=exact → Content-Range). */
export async function countRows(page: Page, path: string): Promise<number> {
  const r = await sb(page, 'GET', path + (path.includes('?') ? '&' : '?') + 'select=id&limit=1', undefined, 'count=exact');
  expect(r.status, `count ${path}`).toBeLessThan(300);
  return Number((r.contentRange ?? '').split('/')[1]);
}
